ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS handmatige_bron text, ADD COLUMN IF NOT EXISTS aangemaakt_door uuid, ADD COLUMN IF NOT EXISTS gekoppeld_onderneming_id uuid REFERENCES public.ondernemingen(id), ADD COLUMN IF NOT EXISTS gekoppeld_persoon_id uuid REFERENCES public.personen(id), ADD COLUMN IF NOT EXISTS status_voor_koppeling public.lead_status;
ALTER TABLE public.aanvraag_concepten ADD COLUMN IF NOT EXISTS gekoppeld_onderneming_id uuid REFERENCES public.ondernemingen(id), ADD COLUMN IF NOT EXISTS gekoppeld_persoon_id uuid REFERENCES public.personen(id), ADD COLUMN IF NOT EXISTS converted_at timestamptz;
CREATE TABLE public.lead_klant_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bron_tabel text NOT NULL, bron_id uuid NOT NULL, onderneming_id uuid NOT NULL REFERENCES public.ondernemingen(id), persoon_id uuid REFERENCES public.personen(id), actie text NOT NULL, notitie text NOT NULL DEFAULT '', uitgevoerd_door uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), is_test boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.lead_klant_log TO authenticated;
GRANT ALL ON public.lead_klant_log TO service_role;
ALTER TABLE public.lead_klant_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_lead_klant_log ON public.lead_klant_log FOR SELECT TO authenticated USING(public.is_team_member(auth.uid()) AND auth.jwt()->>'aal'='aal2' AND (NOT is_test OR public.is_supervisor_or_admin(auth.uid())));
CREATE OR REPLACE FUNCTION public.a19_team() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.is_team_member(auth.uid()) OR coalesce(auth.jwt()->>'aal','')<>'aal2' THEN RAISE EXCEPTION 'Log in als teamlid met je tweestapscode' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION public.a19_team() FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.a19_team() TO authenticated;
CREATE OR REPLACE FUNCTION public.handmatige_lead_dubbelcheck(_email text,_telefoon text,_kvk text,_is_test boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE result jsonb; BEGIN PERFORM public.a19_team(); IF _is_test AND NOT public.is_supervisor_or_admin(auth.uid()) THEN RAISE EXCEPTION 'Geen toegang tot testrecords'; END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'titel',titel,'link',link,'bron',bron)),'[]'::jsonb) INTO result FROM (
SELECT DISTINCT b.id,b.bron,b.titel,CASE WHEN b.onderneming_id IS NOT NULL THEN '/admin/klanten/'||public.onderneming_hoofdkaart(b.onderneming_id) WHEN b.bron='ondernemingen' THEN '/admin/klanten/'||public.onderneming_hoofdkaart(b.id) WHEN b.lead_id IS NOT NULL THEN '/admin/leads/'||b.lead_id ELSE b.route||b.id END link FROM public.admin_zoek_bronnen b
WHERE b.bron IN ('leads','ondernemingen','personen','bav_aanmeldingen','aanvraag_concepten') AND b.is_test=_is_test AND ((nullif(btrim(_email),'') IS NOT NULL AND lower(btrim(b.email))=lower(btrim(_email))) OR (nullif(public.zoek_norm_tel(_telefoon),'') IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(b.telefoons) p WHERE public.zoek_norm_tel(p)=public.zoek_norm_tel(_telefoon))) OR (nullif(public.zoek_norm_compact(_kvk),'') IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(b.nummers) n WHERE public.zoek_norm_compact(n)=public.zoek_norm_compact(_kvk))))
) matches; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.handmatige_lead_toevoegen(_gegevens jsonb,_toch_nieuw boolean DEFAULT false,_is_test boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v uuid; email text:=lower(btrim(coalesce(_gegevens->>'email',''))); tel text:=CASE WHEN public.zoek_norm_tel(_gegevens->>'telefoon') IS NOT NULL THEN '0'||public.zoek_norm_tel(_gegevens->>'telefoon') END; kvk text:=public.zoek_norm_compact(_gegevens->>'kvk'); bron text:=_gegevens->>'bron'; dubbel jsonb; BEGIN
PERFORM public.a19_team(); IF _is_test AND NOT public.is_supervisor_or_admin(auth.uid()) THEN RAISE EXCEPTION 'Geen toegang tot testrecords'; END IF;
IF length(btrim(coalesce(_gegevens->>'voornaam','')))=0 OR length(btrim(coalesce(_gegevens->>'achternaam','')))=0 THEN RAISE EXCEPTION 'Voornaam en achternaam zijn verplicht'; END IF;
IF email='' AND coalesce(tel,'')='' THEN RAISE EXCEPTION 'Vul minstens e-mail of telefoon in'; END IF;
IF email<>'' AND email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]{2,}$' THEN RAISE EXCEPTION 'Vul een geldig e-mailadres in'; END IF;
IF nullif(btrim(_gegevens->>'telefoon'),'') IS NOT NULL AND (tel IS NULL OR tel !~ '^0[1-9][0-9]{8}$') THEN RAISE EXCEPTION 'Vul een geldig Nederlands telefoonnummer in'; END IF;
IF kvk<>'' AND (kvk !~ '^[0-9]{8}$' OR kvk ~ '^([0-9])\1{7}$') THEN RAISE EXCEPTION 'Vul een geldig KvK-nummer in'; END IF;
IF bron IS NULL OR bron NOT IN ('telefoon','mail','netwerk','partner','beurs','overig') OR coalesce(_gegevens->>'interesse','') NOT IN ('bav_avb','cyber','aov','overig') THEN RAISE EXCEPTION 'Kies bron en interesse'; END IF;
IF length(coalesce(_gegevens->>'notitie',''))>2000 OR length(coalesce(_gegevens->>'beroep',''))>1000 OR length(_gegevens::text)>12000 THEN RAISE EXCEPTION 'Invoer is te lang'; END IF;
IF _is_test AND email<>'' AND email !~ '@zpzaken\.nl$' THEN RAISE EXCEPTION 'Testmail moet @zpzaken.nl zijn'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(email||'|'||coalesce(tel,'')||'|'||kvk,0));
dubbel:=public.handmatige_lead_dubbelcheck(email,tel,kvk,_is_test); IF jsonb_array_length(dubbel)>0 AND NOT coalesce(_toch_nieuw,false) THEN RETURN jsonb_build_object('dubbel',dubbel); END IF;
INSERT INTO public.leads(type,voornaam,achternaam,email,telefoon,bedrijfsnaam,kvk_nummer,beroep,verzekering_type,bron,handmatige_bron,aangemaakt_door,bericht,is_test,extra_data)
VALUES('handmatig',btrim(_gegevens->>'voornaam'),btrim(_gegevens->>'achternaam'),email,nullif(tel,''),nullif(btrim(_gegevens->>'bedrijfsnaam'),''),nullif(kvk,''),nullif(btrim(_gegevens->>'beroep'),''),_gegevens->>'interesse',(CASE WHEN bron='mail' THEN 'email' ELSE bron END)::public.lead_bron,bron,auth.uid(),btrim(_gegevens->>'notitie'),_is_test,jsonb_build_object('interesse',_gegevens->>'interesse','handmatig',true)) RETURNING id INTO v;
IF nullif(_gegevens->>'opvolgdatum','') IS NOT NULL THEN PERFORM set_config('zp.vlag_rpc','1',true); UPDATE public.leads SET vlag='later',vlag_notitie=left(coalesce(nullif(btrim(_gegevens->>'notitie'),''),'Handmatige lead opvolgen'),500),vlag_datum=(_gegevens->>'opvolgdatum')::date,vlag_door=auth.uid(),vlag_op=now() WHERE id=v; END IF;
INSERT INTO public.activiteiten_log(actie_type,omschrijving,uitgevoerd_door,lead_id,is_test) VALUES('handmatige_lead','Handmatige lead toegevoegd via '||bron||CASE WHEN jsonb_array_length(dubbel)>0 THEN '; bewust nieuwe lead ondanks overeenkomst' ELSE '' END,auth.uid(),v,_is_test);
RETURN jsonb_build_object('id',v); END $$;
DO $$ DECLARE d text; nieuw text; BEGIN d:=pg_get_functiondef('public.koppel_bronrecord_aan_persoon()'::regprocedure); nieuw:=replace(d,'  -- Velden per bron', E'  IF TG_ARGV[0] = ''leads'' AND NEW.type::text = ''handmatig'' THEN RETURN NEW; END IF;\n  -- Velden per bron'); IF nieuw=d THEN RAISE EXCEPTION 'Manual person guard missing'; END IF; EXECUTE nieuw; END $$;
CREATE OR REPLACE FUNCTION public.lead_klant_koppelen(_bron_tabel text,_bron_id uuid,_onderneming_id uuid,_persoon_id uuid DEFAULT NULL,_notitie text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE ond uuid; l public.leads; c public.aanvraag_concepten; test boolean; pers uuid:=_persoon_id; BEGIN
PERFORM public.a19_team(); ond:=public.onderneming_hoofdkaart(_onderneming_id);
IF NOT EXISTS(SELECT 1 FROM public.ondernemingen WHERE id=ond) THEN RAISE EXCEPTION 'Klantkaart niet gevonden'; END IF;
IF _bron_tabel='leads' THEN SELECT * INTO l FROM public.leads WHERE id=_bron_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Lead niet gevonden'; END IF; IF l.gekoppeld_onderneming_id IS NOT NULL THEN RAISE EXCEPTION 'Ontkoppel eerst de bestaande koppeling'; END IF; IF l.status IN ('gepauzeerd','opgezegd') THEN RAISE EXCEPTION 'Een beëindigde of gepauzeerde polis niet via klantkoppeling wijzigen'; END IF; test:=l.is_test;
ELSIF _bron_tabel='aanvraag_concepten' THEN SELECT * INTO c FROM public.aanvraag_concepten WHERE id=_bron_id FOR UPDATE; IF NOT FOUND OR c.geanonimiseerd_op IS NOT NULL THEN RAISE EXCEPTION 'Concept niet beschikbaar'; END IF; IF c.gekoppeld_onderneming_id IS NOT NULL THEN RAISE EXCEPTION 'Ontkoppel eerst de bestaande koppeling'; END IF; test:=c.is_test;
ELSE RAISE EXCEPTION 'Onbekende leadbron'; END IF;
IF (test AND NOT public.is_supervisor_or_admin(auth.uid())) OR (SELECT is_test FROM public.ondernemingen WHERE id=ond) IS DISTINCT FROM test THEN RAISE EXCEPTION 'Test en echte klantgegevens niet mengen'; END IF;
IF pers IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.persoon_onderneming po JOIN public.personen p ON p.id=po.persoon_id WHERE po.persoon_id=pers AND public.onderneming_hoofdkaart(po.onderneming_id)=ond AND p.is_test=test) THEN RAISE EXCEPTION 'Contactpersoon hoort niet bij deze klant'; END IF;
IF pers IS NULL THEN INSERT INTO public.personen(voornaam,achternaam,email_weergave,genormaliseerd_email,telefoon,is_test) VALUES(coalesce(l.voornaam,c.voornaam),coalesce(l.achternaam,c.achternaam),nullif(coalesce(l.email,c.email),''),nullif(lower(coalesce(l.email,c.email)),''),coalesce(l.telefoon,c.telefoon),test) RETURNING id INTO pers; INSERT INTO public.persoon_onderneming(persoon_id,onderneming_id) VALUES(pers,ond); END IF;
PERFORM set_config('zp.a19_rpc','1',true);
IF _bron_tabel='leads' THEN UPDATE public.leads SET gekoppeld_onderneming_id=ond,gekoppeld_persoon_id=pers,status_voor_koppeling=status,status='klant',converted_at=now() WHERE id=_bron_id;
ELSE UPDATE public.aanvraag_concepten SET gekoppeld_onderneming_id=ond,gekoppeld_persoon_id=pers,converted_at=now() WHERE id=_bron_id; END IF;
INSERT INTO public.lead_klant_log(bron_tabel,bron_id,onderneming_id,persoon_id,actie,notitie,uitgevoerd_door,is_test) VALUES(_bron_tabel,_bron_id,ond,pers,'gekoppeld',left(coalesce(_notitie,''),2000),auth.uid(),test);
INSERT INTO public.activiteiten_log(actie_type,omschrijving,uitgevoerd_door,lead_id,is_test) VALUES('lead_klant_gekoppeld','Lead gekoppeld aan klantkaart '||ond||'. '||left(coalesce(_notitie,''),2000),auth.uid(),CASE WHEN _bron_tabel='leads' THEN _bron_id END,test);
RETURN jsonb_build_object('onderneming_id',ond,'persoon_id',pers); END $$;
CREATE OR REPLACE FUNCTION public.lead_klant_ontkoppelen(_bron_tabel text,_bron_id uuid,_notitie text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE ond uuid; pers uuid; test boolean; BEGIN PERFORM public.a19_team(); IF NOT(public.is_supervisor_or_admin(auth.uid()) OR lower(coalesce(auth.jwt()->>'email',''))='ellen.baars@zpzaken.nl') THEN RAISE EXCEPTION 'Alleen Ellen of supervisor mag ontkoppelen' USING ERRCODE='42501'; END IF; IF length(btrim(coalesce(_notitie,'')))<3 OR length(_notitie)>2000 THEN RAISE EXCEPTION 'Notitie verplicht (3 tot 2000 tekens)'; END IF;
PERFORM set_config('zp.a19_rpc','1',true);
IF _bron_tabel='leads' THEN SELECT gekoppeld_onderneming_id,gekoppeld_persoon_id,is_test INTO ond,pers,test FROM public.leads WHERE id=_bron_id FOR UPDATE; IF ond IS NULL THEN RAISE EXCEPTION 'Geen klantkoppeling'; END IF; UPDATE public.leads SET gekoppeld_onderneming_id=NULL,gekoppeld_persoon_id=NULL,status=coalesce(status_voor_koppeling,'nieuw'),converted_at=NULL,status_voor_koppeling=NULL WHERE id=_bron_id;
ELSIF _bron_tabel='aanvraag_concepten' THEN SELECT gekoppeld_onderneming_id,gekoppeld_persoon_id,is_test INTO ond,pers,test FROM public.aanvraag_concepten WHERE id=_bron_id FOR UPDATE; IF ond IS NULL THEN RAISE EXCEPTION 'Geen klantkoppeling'; END IF; UPDATE public.aanvraag_concepten SET gekoppeld_onderneming_id=NULL,gekoppeld_persoon_id=NULL,converted_at=NULL WHERE id=_bron_id;
ELSE RAISE EXCEPTION 'Onbekende leadbron'; END IF;
INSERT INTO public.lead_klant_log(bron_tabel,bron_id,onderneming_id,persoon_id,actie,notitie,uitgevoerd_door,is_test) VALUES(_bron_tabel,_bron_id,ond,pers,'ontkoppeld',btrim(_notitie),auth.uid(),test);
INSERT INTO public.activiteiten_log(actie_type,omschrijving,uitgevoerd_door,lead_id,is_test) VALUES('lead_klant_ontkoppeld','Lead ontkoppeld: '||btrim(_notitie),auth.uid(),CASE WHEN _bron_tabel='leads' THEN _bron_id END,test); END $$;
CREATE OR REPLACE FUNCTION public.guard_a19_koppeling() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF coalesce(current_setting('zp.a19_rpc',true),'')<>'1' AND (NEW.gekoppeld_onderneming_id IS DISTINCT FROM OLD.gekoppeld_onderneming_id OR NEW.gekoppeld_persoon_id IS DISTINCT FROM OLD.gekoppeld_persoon_id OR (TG_TABLE_NAME='leads' AND to_jsonb(OLD)->>'type'<>'verzekering_aanvraag' AND OLD.gekoppeld_onderneming_id IS NOT NULL AND (to_jsonb(NEW)->>'status' IS DISTINCT FROM to_jsonb(OLD)->>'status' OR NEW.converted_at IS DISTINCT FROM OLD.converted_at))) THEN RAISE EXCEPTION 'Klantkoppeling alleen wijzigen via Koppel aan klant'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_a19_koppeling BEFORE UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.guard_a19_koppeling();
CREATE TRIGGER guard_a19_koppeling BEFORE UPDATE ON public.aanvraag_concepten FOR EACH ROW EXECUTE FUNCTION public.guard_a19_koppeling();
REVOKE ALL ON FUNCTION public.guard_a19_koppeling() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.handmatige_lead_dubbelcheck(text,text,text,boolean),public.handmatige_lead_toevoegen(jsonb,boolean,boolean),public.lead_klant_koppelen(text,uuid,uuid,uuid,text),public.lead_klant_ontkoppelen(text,uuid,text) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.handmatige_lead_dubbelcheck(text,text,text,boolean),public.handmatige_lead_toevoegen(jsonb,boolean,boolean),public.lead_klant_koppelen(text,uuid,uuid,uuid,text),public.lead_klant_ontkoppelen(text,uuid,text) TO authenticated;
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.tel_dashboard_opbouw()'::regprocedure); d:=replace(d,'''offerte'',count(*) FILTER(WHERE type=''offerte-aanvraag'')','''offerte'',count(*) FILTER(WHERE type=''offerte-aanvraag''),''handmatig'',count(*) FILTER(WHERE type::text=''handmatig''),''handmatige_bronnen'',(SELECT coalesce(jsonb_object_agg(bron,n),''{}''::jsonb) FROM (SELECT handmatige_bron bron,count(*) n FROM public.leads WHERE type::text=''handmatig'' AND NOT coalesce(is_test,false) GROUP BY handmatige_bron) z)'); d:=replace(d,'+(l->>''offerte'')::bigint','+(l->>''offerte'')::bigint+(l->>''handmatig'')::bigint'); IF position('handmatige_bronnen' IN d)=0 THEN RAISE EXCEPTION 'Lead composition guard missing'; END IF; EXECUTE d; END $$;